INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_ADJECTIVE','Sabaean');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_ATTACKED_1','You would take the waters we have guarded for generations? Our people will resist.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CISTERN','Ma''rib Cistern');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CISTERN_HELP','Replaces Water Mill and retains all its normal Community Patch benefits and construction requirements. Adds +1 [ICON_FOOD] Food and +1 [ICON_GOLD] Gold as flat city yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CISTERN_PEDIA','Ancient Ma''rib depended on the management of seasonal water. Dressed-stone structures guided floodwater into channels and fields, supporting an oasis at the edge of the desert. The Ma''rib Cistern is a small-scale gameplay tribute to that engineering tradition, rather than a claim that the ancient city used a medieval water-powered mill.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CISTERN_STRATEGY','Build Cisterns wherever the normal Water Mill is legal. Their additional Food supports growth and their Gold helps the treasury. In a Desert River city, the Cistern and civilization ability together add +2 Food, +1 Production, +1 Culture and +1 Gold beyond an ordinary Water Mill.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CITY_1','Ma''rib');
