INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CITY_9','Al-Asahil');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CIV','The Kingdom of Saba');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CIV5_HEADING_1','The Valleys of Saba');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CIV5_TEXT_1','Saba was an ancient kingdom of South Arabia, centered on Ma''rib in present-day Yemen. Its communities combined farming in an arid landscape with exchange along the incense routes. Temples, inscriptions and monumental masonry preserve evidence of a prosperous and organized society.[NEWLINE][NEWLINE]Water management made cultivation possible. Sluices and canals distributed seasonal flows to fields around Ma''rib. This civilization represents that tradition through modest city yields; it does not transform Desert tiles or spread irrigation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_CIV_PEDIA','Saba was an ancient kingdom of South Arabia, centered on Ma''rib in present-day Yemen. Its communities combined farming in an arid landscape with exchange along the incense routes. Temples, inscriptions and monumental masonry preserve evidence of a prosperous and organized society.[NEWLINE][NEWLINE]Water management made cultivation possible. Sluices and canals distributed seasonal flows to fields around Ma''rib. This civilization represents that tradition through modest city yields; it does not transform Desert tiles or spread irrigation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_DAWN','Karib''il Watar, ruler of mighty Saba, the people of the southern deserts look to your wisdom once more.[NEWLINE][NEWLINE]Where others see barren earth, your people see fertile valleys waiting to be awakened. Through ingenious irrigation and enduring determination, your kingdom has prospered beneath the desert sun.[NEWLINE][NEWLINE]Guard the waters of your homeland, strengthen the cities of your people, and let the wealth of Saba spread across the known world.[NEWLINE][NEWLINE]Will you transform the desert into a land of abundance, and build a kingdom remembered throughout the ages?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_DEFEAT_1','Our gates have fallen. May those who follow remember how we brought water to the desert.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_DUMMY','Sabaean Water Management');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_DUMMY_HELP','Automatically maintained city-location yields. Cannot be constructed, purchased or sold.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_FRIENDLY_1','A trusted guest returns. Come, let us speak where the water runs cool.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_GREETING_1','I am Karib''il Watar of Saba. May your journey find shade, clear water and an honorable welcome.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_HOSTILE_1','Your promises have grown as dry as an empty channel. Speak carefully.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_KARIBIL_HEADING_1','Land, Water and Royal Power');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_KARIBIL_LIVED','Early first millennium BCE');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_KARIBIL_NAME','Karib''il Watar');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_KARIBIL_SUBTITLE','Ruler of Saba');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_KARIBIL_TEXT_1','Karib''il Watar was a ruler of early Saba whose inscriptions at Sirwah describe campaigns, alliances and the organization of territory. Royal power joined military action with control over settlements, land and water. The chronology of early Sabaean rulers remains a subject of scholarship.[NEWLINE][NEWLINE]Here he leads a historically inspired kingdom focused on prosperous settlements. His portrait and diplomacy are original artistic interpretations, not surviving likenesses or quotations.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_KARIBIL_TITLES_1','Mukarrib of Saba');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_LEADER','Karib''il Watar');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_LEADER_PEDIA','Karib''il Watar was a ruler of early Saba whose inscriptions at Sirwah describe campaigns, alliances and the organization of territory. Royal power joined military action with control over settlements, land and water. The chronology of early Sabaean rulers remains a subject of scholarship.[NEWLINE][NEWLINE]Here he leads a historically inspired kingdom focused on prosperous settlements. His portrait and diplomacy are original artistic interpretations, not surviving likenesses or quotations.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_NEUTRAL_1','You stand before the ruler of Saba. State your purpose.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_PEACE_1','Let the fields be tended and the roads opened again. Saba accepts this peace.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_PEACE_OFFER_1','Our peoples have paid enough for war. Let us restore the channels of peace.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_PROMOTION','Guardian of the Wadi');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_PROMOTION_HELP','+15% Combat Strength when defending on Desert, including Desert Hills. +1 Sight. Lost on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SHORT','Saba');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_1','Yada''il');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_10','Wahab''il');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_2','Sumhu''ali');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_3','Dhamar''ali');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_4','Yitha''amar');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_5','Hawfi''amm');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_6','Abikarib');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_7','Ilsharah');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_8','Nashakarib');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_SPY_9','Yakrubmalik');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_STRATEGY','Seek River sites for Food and Production, and Desert city centers for Culture. The bonuses stack, including on Desert Hills. Develop Ma''rib Cisterns under the normal Water Mill requirements and defend vulnerable Desert settlements with Wadi Sentinels. Growth supports Science, while settlement Culture supports Social Policies; the ability grants neither direct Science nor Tourism.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_TRADE_1','An honorable exchange. May our merchants travel safely between our lands.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_TRAIT','Where the Desert Blooms');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_TRAIT_HELP','Cities on Rivers receive +1 [ICON_FOOD] Food and +1 [ICON_PRODUCTION] Production. Cities founded on Desert (including Desert Hills) receive +1 [ICON_CULTURE] Culture. These flat city bonuses stack and apply while Saba controls the city, including acquired cities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_UNIT','Wadi Sentinel');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_UNIT_HELP','Replaces Spearman, retaining its normal Community Patch properties. +15% Combat Strength when defending on Desert, including Desert Hills, and +1 Sight. Both unique bonuses are lost on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_UNIT_PEDIA','The Wadi Sentinel represents the guards of South Arabian settlements and the channels that sustained them. A spear and shield could protect a caravan road or a sluice gate; knowledge of dry valleys mattered as much as equipment. This historically inspired unit uses the ordinary Spearman model. Its unique defensive training and extra Sight expire on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_UNIT_STRATEGY','Station Wadi Sentinels on Desert approaches to your settlements. Their extra Sight helps identify threats. The unique strength bonus applies only while defending on the unit''s own Desert tile; it gives no attacking bonus and does not require friendly territory. Upgrade normally when stronger units become available.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_SABA_WAR_1','You have threatened the peace of our valleys. The spears of Saba will answer.');
